using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Reflection;using System.Windows.Forms;using BeamScheduleFormatter;
class PowPolishUiTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static T Get<T>(object o,string name){return (T)o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}static object Call(object o,string name,params object[] args){return o.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,args);}
 [STAThread]static void Main(){Application.EnableVisualStyles();AccessCodes.Granted=true;using(var f=new ProgramOfWorksForm()){var sheets=Get<Dictionary<string,ExtraWorkGrid>>(f,"extraGrids");Check(sheets["StructuralColumn"].Grid.Columns[8].Visible&&sheets["StructuralColumn"].Grid.Columns[9].Visible,"Both column main-bar groups visible");foreach(var item in sheets.Values){if(item.Key=="Trees")continue;var g=item.Grid;bool old=Get<bool>(f,"filling");f.GetType().GetField("filling",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(f,true);int n=g.Rows.Add();typeof(WorksDataGridView).GetMethod("OnDefaultValuesNeeded",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(g,new object[]{new DataGridViewRowEventArgs(g.Rows[n])});Check(g.Rows[n].Cells.Cast<DataGridViewCell>().Where(c=>!c.ReadOnly).All(c=>!QuantityInputDefaults.IsNumber(c.Value)),"No numeric prefill in "+item.Kind);g.Rows.RemoveAt(n);f.GetType().GetField("filling",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(f,old);}var foot=Get<DataGridView>(f,"footings");Check(foot.Columns[6].Visible,"Actual footing depth is visible");var methods=Get<ComboBox[]>(f,"footingInputMethods");Check(!foot.Columns.Contains("FootingBarMethod0"),"Input methods are not duplicated per worksheet row");methods[0].SelectedIndex=1;Check(foot.Columns[10].Visible&&!foot.Columns[9].Visible,"Selecting bar count in settings activates the correct worksheet input");}
 using(var form=new Form{Width=1000,Height=500}){var tabs=new NavigationTabs{Dock=DockStyle.Fill,Font=new Font("Segoe UI",10,FontStyle.Bold)};foreach(string title in new[]{"Bill of Quantities","Reinforced Concrete Works","Carpentry and Joinery Works","Pavement Construction","Slope Protection Works"})tabs.TabPages.Add(title);form.Controls.Add(tabs);form.Show();Application.DoEvents();for(int i=0;i<tabs.TabCount;i++)Check(tabs.GetTabRect(i).Width>=TextRenderer.MeasureText(tabs.TabPages[i].Text,tabs.Font,Size.Empty,TextFormatFlags.NoPadding|TextFormatFlags.NoPrefix|TextFormatFlags.SingleLine).Width+16,"Full tab caption fits: "+tabs.TabPages[i].Text);Check(!NavigationTabs.KeyboardFocusVisible(tabs),"Native dotted focus indicator suppressed without disabling keyboard tabs");}
 using(var form=new Form())using(var grid=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false}){for(int i=0;i<4;i++)grid.Columns.Add("C"+i,"C"+i);form.Controls.Add(grid);int p=grid.Rows.Add("900(1)d","Structural concrete",30.7027,"m3"),c=grid.Rows.Add("","Source",1.8725,"m3"),other=grid.Rows.Add("900(1)d","Different specification",8,"m3");BoqDisclosure.Parent(grid.Rows[p],"slot-A");BoqDisclosure.Detail(grid.Rows[c],"slot-A");BoqDisclosure.Parent(grid.Rows[other],"slot-B");var view=new BoqDisclosure(grid);form.Show();Application.DoEvents();view.Apply();Check(!grid.Rows[c].Visible,"Source breakdown starts collapsed");view.Toggle(grid.Rows[p]);grid.CurrentCell=grid.Rows[c].Cells[1];view.Toggle(grid.Rows[p]);Check(!grid.Rows[c].Visible&&grid.Rows[p].Visible&&grid.Rows[other].Visible,"Collapse hides only the selected pay item's source rows");Check(Convert.ToDouble(grid.Rows[p].Cells[2].Value)==30.7027,"Collapsing does not change parent quantity");view.Apply();Check(!grid.Rows[c].Visible,"Collapse state survives view refresh");view.Toggle(grid.Rows[p]);Check(grid.Rows[c].Visible,"Arrow expands sources again");}
 Console.WriteLine("PASS: "+checks+" native blank-row, footing method, tab-fit and BOQ disclosure checks");}
}
